            "id": "bier-turas",
            "category": "bier",
            "title": "Turas",
            "subtitle": "Die Reise · Seefahrerbier",
            "image": "./public/assets/gortach-brauerei/bier-turas.png",
            "imageFormat": "portrait",
            "imageFit": "contain",
