            "id": "whisky-turas-18",
            "category": "whisky",
            "title": "Caddach Gortach · 18 Jahre · Turas",
            "subtitle": "Albischer Whisky · ungetorft",
            "image": "./public/assets/gortach-brauerei/whisky-turas-18.png",
